      (value.matchIndex === matches.length - 1 && current.results.length === 2)) return null;
  } else {
    if (current.results.length > 1) return null;
    if (phase === TournamentPhase.ready && game) return null;
    if (phase === TournamentPhase.playing &&
      (!game || isWon(game) || game.boardCode !== current.boardCode)) return null;
