import { useEffect, useImperativeHandle, useRef } from 'react';
import { Board } from '../board/Board.tsx';
import { GameStatus } from '../status/GameStatus.tsx';
import { useGame } from '../session/use-game.ts';
import type { RefObject } from 'react';
import type { BoardFocus } from '../board/Board.tsx';
import type { GameState } from '../game.ts';

export interface TournamentTurnHandle { currentGame(): GameState }
interface TournamentTurnProps {
  game: GameState;
  ref: RefObject<TournamentTurnHandle | null>;
  completed(game: GameState): void;
  announce(message: string): void;
}

export function TournamentTurn({ game, ref, completed, announce }: TournamentTurnProps) {
  const controller = useGame(game);
  const board = useRef<BoardFocus>(null);
  const { session } = controller;
  useImperativeHandle(ref, () => ({ currentGame: controller.currentGame }));
  useEffect(() => {
    if (session.feedback) announce(session.feedback);
  }, [session.announcement, session.feedback, announce]);
  return <>
    <GameStatus game={session.game} best={undefined} celebration={session.celebration} tournament />
    <p id="board-help" className="help">
      Use a pointer or Tab to enter the board. Arrow keys move between cards. Enter or Space reveals a card.
    </p>
    <Board game={session.game} ref={board} activate={(index) => completed(controller.activate(index))} />
  </>;
}

