import type { ReactNode } from 'react';
import type { GameState } from '../game.ts';
import type { TournamentState } from './rules.ts';
import type { TournamentTurnHandle } from './TournamentTurn.tsx';
import './tournament.css';

interface TournamentProps {
  back(): void;
  announce(message: string): void;
  status: ReactNode;
}

export function Tournament({ back, announce, status }: TournamentProps) {
  const [state, setState] = useState(tournamentDraft);
  const [store] = useState(browserStore);
  const [history, setHistory] = useState(() => readTournaments(store));
  const [problem, setProblem] = useState('');
  const [notice, setNotice] = useState('');
  const [leave, setLeave] = useState<(() => void) | null>(null);
  const [loadedTurn, setLoadedTurn] = useState(false);
  const [generation, setGeneration] = useState(0);
  const heading = useRef<HTMLHeadingElement>(null);
  const turn = useRef<TournamentTurnHandle>(null);
  const match = state.matches[state.matchIndex];
  const complete = state.phase === TournamentPhase.complete;
  const setup = state.phase === TournamentPhase.setup;
  const winner = complete ? matchWinner(state, state.matches.length - 1) : null;
  const turnIndex = (match?.results.length ?? 0) - (state.phase === TournamentPhase.result ? 1 : 0);
  const player = matchPlayers(state, state.matchIndex)[turnIndex];
  const name = player === undefined ? '' : (state.names[player] ?? '');
  const round = roundFor(state.names.length, state.matchIndex);

  useEffect(() => {
    heading.current?.focus();
  }, [state.phase, state.matchIndex, match?.results.length, loadedTurn, generation]);

  function adopt(next: TournamentState): void {
    setState(next);
    setLoadedTurn(next.phase === TournamentPhase.playing);
    setGeneration((value) => value + 1);
    setProblem('');
    if (next.phase === TournamentPhase.complete)
      setHistory((previous) => saveTournament(store, previous, next));
    announce(
      next.phase === TournamentPhase.complete
        ? `Champion: ${next.names[matchWinner(next, next.matches.length - 1) ?? 0]}`
        : next.phase === TournamentPhase.setup
          ? 'Tournament setup.'
          : 'Loaded tournament. Select Start turn to play.',
    );
  }

  function confirm(action: () => void): void {
    if (!setup && !complete) setLeave(() => action);
    else action();
  }

  function start(): void {
    const error = nameProblem(state.names);
    setProblem(error);
    if (error) {
      announce(error);
      return;
    }
    const next = createTournament(state.names, tournamentDeals(state.names.length));
    setState(next);
    const first = matchPlayers(next, 0)[0] ?? 0;
    announce(`Round: ${roundFor(next.names.length, 0).name}. Now playing: ${next.names[first]}`);
  }

  function played(game: GameState): void {
    const next = recordTurn(state, game);
    setState(next);
    if (!isWon(game)) return;
    const champion = matchWinner(next, next.matchIndex);
    announce(
      `Pair found. All pairs found in ${game.moves} moves and ${formatElapsed(game.elapsedMs)}. ` +
        (next.phase === TournamentPhase.complete
          ? `Champion: ${next.names[champion ?? 0]}`
          : `${name} finished.`),
    );
    if (next.phase === TournamentPhase.complete)
      setHistory((previous) => saveTournament(store, previous, next));
  }

  function load(text: string): void {
    const decoded = decodeTournament(text);
    if (!decoded.state) {
      setNotice(decoded.problem);
      announce(decoded.problem);
      return;
    }
    const accepted = decoded.state;
    confirm(() => {
      adopt(accepted);
      setNotice('Loaded tournament.');
    });
  }

  return (
    <section className="tournament">
      <h2 ref={heading} tabIndex={-1}>
        {complete ? 'Tournament complete' : setup ? 'Tournament' : 'Tournament match'}
      </h2>
      {setup ? (
        <Setup state={state} change={setState} start={start} problem={problem} />
      ) : (
        <>
          {complete ? (
            <p className="victory">Champion: {winner === null ? '' : state.names[winner]}</p>
          ) : (
            <>
              <p>Round: {round.name}</p>
              <p>Now playing: {name}</p>
              {state.phase === TournamentPhase.ready || loadedTurn ? (
                <button
                  type="button"
                  className="control"
                  onClick={() => {
                    setLoadedTurn(false);
                    setState(startTurn(state));
                    announce(`Now playing: ${name}`);
                  }}
                >
                  Start turn
                </button>
              ) : null}
              {state.phase === TournamentPhase.result && (
                <>
                  <p>
                    {name} finished in {match?.results.at(-1)?.moves} moves and{' '}
                    {formatElapsed(match?.results.at(-1)?.elapsedMs ?? 0)}.
                  </p>
                  {match?.results.length === 2 && (
                    <p>Winner: {state.names[matchWinner(state, state.matchIndex) ?? 0]}</p>
                  )}
                  <button
                    type="button"
                    className="control"
                    onClick={() => {
                      const next = nextTurn(state);
                      setState(next);
                      const nextPlayer = matchPlayers(next, next.matchIndex)[
                        next.matches[next.matchIndex]?.results.length ?? 0
                      ];
                      announce(
                        `Round: ${roundFor(next.names.length, next.matchIndex).name}. Now playing: ${next.names[nextPlayer ?? 0]}`,
                      );
                    }}
                  >
                    {match?.results.length === 2 ? 'Next match' : 'Next turn'}
                  </button>
                </>
              )}
            </>
          )}
        </>
      )}
      {status}
      {state.game && !loadedTurn && (
        <TournamentTurn
          key={generation + ':' + state.matchIndex + ':' + match?.results.length}
          ref={turn}
          game={state.game}
          completed={played}
          announce={announce}
        />
      )}
      {!setup && <Bracket state={state} />}
      <div className="tournament-actions">
        <button type="button" className="control" onClick={() => confirm(back)}>
          {setup || complete ? 'Back to game' : 'Leave tournament'}
        </button>
      </div>
      <Exchange
        notice={notice}
        loadTournament={load}
        exportTournament={() => {
          const game = turn.current?.currentGame() ?? state.game;
          return encodeTournament({ ...state, game });
        }}
      />
      {setup && (
        <section className="past-tournaments">
          <h3>Past tournaments</h3>
          {history.blocked && <p>{STORAGE_NOTICE}</p>}
          {history.items.length === 0 ? (
            <p>No finished tournaments yet.</p>
          ) : (
            <ul>
              {history.items.map((item, index) => (
                <li key={index}>
                  <button type="button" className="control" onClick={() => adopt(item)}>
                    {item.names.length} players · Champion:{' '}
                    {item.names[matchWinner(item, item.matches.length - 1) ?? 0]}
                  </button>
                </li>
              ))}
            </ul>
          )}
        </section>
      )}
      <LeaveDialog leave={leave} close={() => setLeave(null)} />
    </section>
  );
}
import { createGame, isWon } from '../game.ts';
import type { GameState } from '../game.ts';

export const TournamentPhase = {
  setup: 'setup',
  ready: 'ready',
  playing: 'playing',
  result: 'result',
  complete: 'complete',
} as const;
type Phase = (typeof TournamentPhase)[keyof typeof TournamentPhase];
export interface TournamentResult {
  readonly moves: number;
  readonly elapsedMs: number;
}
export interface TournamentMatch {
  readonly boardCode: string;
  readonly results: readonly TournamentResult[];
}
export interface TournamentState {
  readonly names: readonly string[];
  readonly matches: readonly TournamentMatch[];
  readonly matchIndex: number;
  readonly phase: Phase;
  readonly game: GameState | null;
}

export function tournamentDraft(count = 4): TournamentState {
  return {
    names: Array.from({ length: count }, () => ''),
    matches: [],
    matchIndex: 0,
    phase: TournamentPhase.setup,
    game: null,
  };
}

export function normalizedNames(names: readonly string[]): string[] {
  return names.map((name) => name.trim().replace(/\s+/gu, ' ').normalize('NFC'));
}

export function nameProblem(names: readonly string[]): string {
  const accepted = normalizedNames(names);
  if (accepted.some((name) => [...name].length < 2 || [...name].length > 20))
    return 'Use 2 to 20 characters.';
  if (new Set(accepted.map((name) => name.toLowerCase())).size !== names.length)
    return 'Each name must be different.';
  return '';
}

export function roundFor(count: number, index: number): { name: string; size: number } {
  if (index === count - 2) return { name: 'Final', size: 8 };
  if (count === 8 && index < 4) return { name: 'Quarterfinal', size: 4 };
  return { name: 'Semifinal', size: 6 };
}

export function createTournament(
  names: readonly string[],
  codes: readonly string[],
): TournamentState {
  return {
    names: normalizedNames(names),
    matches: codes.map((boardCode) => ({ boardCode, results: [] })),
    matchIndex: 0,
    phase: TournamentPhase.ready,
    game: null,
  };
}

export function matchPlayers(state: TournamentState, index: number): readonly number[] {
  const opening =
    state.names.length === 4
      ? [
          [0, 3],
          [1, 2],
        ]
      : [
          [0, 7],
          [3, 4],
          [2, 5],
          [1, 6],
        ];
  if (index < opening.length) return opening[index] ?? [];
  const previous = (index - opening.length) * 2;
  const first = matchWinner(state, previous);
  const second = matchWinner(state, previous + 1);
  return first === null || second === null ? [] : [first, second];
}

export function matchWinner(state: TournamentState, index: number): number | null {
  const results = state.matches[index]?.results;
  if (!results || results.length !== 2) return null;
  const [first, second] = results;
  const [a, b] = matchPlayers(state, index);
  if (!first || !second || a === undefined || b === undefined) return null;
  const difference = first.moves - second.moves || first.elapsedMs - second.elapsedMs || a - b;
  return difference <= 0 ? a : b;
}

export function startTurn(state: TournamentState): TournamentState {
  const match = state.matches[state.matchIndex];
  if (state.phase !== TournamentPhase.ready || !match) return state;
  return { ...state, phase: TournamentPhase.playing, game: createGame(match.boardCode) };
}

export function recordTurn(state: TournamentState, game: GameState): TournamentState {
  const match = state.matches[state.matchIndex];
  if (state.phase !== TournamentPhase.playing || !match || game.boardCode !== match.boardCode)
    return state;
  if (!isWon(game)) return { ...state, game };
  const results = [...match.results, { moves: game.moves, elapsedMs: game.elapsedMs }];
  const matches = state.matches.map((item, index) =>
    index === state.matchIndex ? { ...item, results } : item,
  );
  const complete = state.matchIndex === matches.length - 1 && results.length === 2;
  return {
    ...state,
    matches,
    game: null,
    phase: complete ? TournamentPhase.complete : TournamentPhase.result,
  };
}

export function nextTurn(state: TournamentState): TournamentState {
  if (state.phase !== TournamentPhase.result) return state;
  const finished = state.matches[state.matchIndex]?.results.length === 2;
  return {
    ...state,
    matchIndex: state.matchIndex + (finished ? 1 : 0),
    phase: TournamentPhase.ready,
    game: null,
  };
}

