import { decodeSnapshot, encodeSnapshot } from '../snapshot.ts';
import { hasExactKeys, isJsonObject, isWithinBytes, parseJson } from '../saved-format.ts';
import { readTournament } from './validation.ts';
import type { TournamentState } from './rules.ts';

export const TOURNAMENT_MAX_BYTES = 262_144;
export const TOURNAMENT_FORMAT = 'neon-pairs/tournament';
export const TOURNAMENT_VERSION = 1;
const KEYS = ['format', 'game', 'matchIndex', 'matches', 'names', 'phase', 'version'];

export function encodeTournament(state: TournamentState): string {
  const game = state.game ? parseJson(encodeSnapshot(state.game)) : null;
  return JSON.stringify(
    { ...state, game, format: TOURNAMENT_FORMAT, version: TOURNAMENT_VERSION },
    (_key, value: unknown) =>
      isJsonObject(value)
        ? Object.fromEntries(Object.entries(value).sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0)))
        : value,
    2,
  );
}

// Unknown keys are diagnosed at every declared object boundary, before accepting data.
function unknownField(value: Record<string, unknown>): string | undefined {
  const root = Object.keys(value).find((key) => !KEYS.includes(key));
  if (root !== undefined) return root;
  if (Array.isArray(value.matches)) {
    for (const match of value.matches) {
      if (!isJsonObject(match)) continue;
      const key = Object.keys(match).find((key) => !['boardCode', 'results'].includes(key));
      if (key !== undefined) return key;
      if (!Array.isArray(match.results)) continue;
      for (const result of match.results) {
        if (!isJsonObject(result)) continue;
        const extra = Object.keys(result).find((key) => !['moves', 'elapsedMs'].includes(key));
        if (extra !== undefined) return extra;
      }
    }
  }
  if (!isJsonObject(value.game)) return undefined;
  const extra = Object.keys(value.game).find(
    (key) =>
      !['version', 'boardCode', 'matched', 'selection', 'moves', 'elapsedMs', 'started'].includes(
        key,
      ),
  );
  if (extra !== undefined) return extra;
  const selection = value.game.selection;
  if (!isJsonObject(selection)) return undefined;
  const fields =
    selection.kind === 'closed'
      ? ['kind']
      : selection.kind === 'one'
        ? ['kind', 'index']
        : ['kind', 'first', 'second', 'remainingMs'];
  return Object.keys(selection).find((key) => !fields.includes(key));
}

export function decodeTournament(text: string): { state: TournamentState | null; problem: string } {
  const invalid = { state: null, problem: 'Invalid tournament.' };
  if (!isWithinBytes(text, TOURNAMENT_MAX_BYTES)) return invalid;
  const value = parseJson(text);
  if (!isJsonObject(value)) return invalid;
  const extra = unknownField(value);
  if (extra !== undefined) return { state: null, problem: `Unknown field: ${extra}.` };
  if (
    !hasExactKeys(value, KEYS) ||
    value.format !== TOURNAMENT_FORMAT ||
    value.version !== TOURNAMENT_VERSION
  )
    return invalid;
  const game = value.game === null ? null : decodeSnapshot(JSON.stringify(value.game));
  if (value.game !== null && game === null) return invalid;
  const state = readTournament(value, game);
  return state ? { state, problem: '' } : invalid;
}
import { parseBoardCode } from '../deck.ts';
import { ELAPSED_MAX_MS, MOVES_MAX, isWon } from '../game.ts';
import { hasExactKeys, isJsonObject, isNonnegativeSafeInteger } from '../saved-format.ts';
import { nameProblem, normalizedNames, roundFor, TournamentPhase } from './rules.ts';
import type { GameState } from '../game.ts';
import type { TournamentMatch, TournamentResult, TournamentState } from './rules.ts';

function readMatch(value: unknown, size: number): TournamentMatch | null {
  if (
    !isJsonObject(value) ||
    !hasExactKeys(value, ['boardCode', 'results']) ||
    typeof value.boardCode !== 'string' ||
    parseBoardCode(value.boardCode)?.size !== size ||
    !Array.isArray(value.results) ||
    value.results.length > 2
  )
    return null;
  const results: TournamentResult[] = [];
  for (const result of value.results) {
    if (
      !isJsonObject(result) ||
      !hasExactKeys(result, ['elapsedMs', 'moves']) ||
      !isNonnegativeSafeInteger(result.moves) ||
      result.moves < (size * size) / 2 ||
      result.moves > MOVES_MAX ||
      typeof result.elapsedMs !== 'number' ||
      !Number.isFinite(result.elapsedMs) ||
      result.elapsedMs < 0 ||
      result.elapsedMs > ELAPSED_MAX_MS
    )
      return null;
    results.push({ moves: result.moves, elapsedMs: result.elapsedMs });
  }
  return { boardCode: value.boardCode, results };
}

export function readTournament(
  value: Record<string, unknown>,
  game: GameState | null,
): TournamentState | null {
  if (
    !Array.isArray(value.names) ||
    ![4, 8].includes(value.names.length) ||
    !value.names.every((name): name is string => typeof name === 'string') ||
    !Array.isArray(value.matches) ||
    !isNonnegativeSafeInteger(value.matchIndex)
  )
    return null;
  const names = value.names;
  const matchIndex = value.matchIndex;
  const phase = Object.values(TournamentPhase).find((phase) => phase === value.phase);
  if (!phase) return null;
  if (phase === TournamentPhase.setup) {
    return value.matches.length === 0 && value.matchIndex === 0 && game === null
      ? { names, matches: [], matchIndex: 0, phase, game: null }
      : null;
  }
  if (
    nameProblem(names) ||
    normalizedNames(names).some((name, i) => name !== names[i]) ||
    value.matches.length !== names.length - 1 ||
    value.matchIndex >= value.matches.length
  )
    return null;
  const matches: TournamentMatch[] = [];
  for (const [index, item] of value.matches.entries()) {
    const match = readMatch(item, roundFor(names.length, index).size);
    if (!match || matches.some((other) => other.boardCode === match.boardCode)) return null;
    matches.push(match);
  }
  const current = matches[value.matchIndex];
  if (
    !current ||
    matches.some((match, index) =>
      index < matchIndex
        ? match.results.length !== 2
        : index > matchIndex && match.results.length !== 0,
    )
  )
    return null;
  if (phase === TournamentPhase.complete) {
    if (value.matchIndex !== matches.length - 1 || current.results.length !== 2 || game)
      return null;
  } else if (phase === TournamentPhase.result) {
    if (
      current.results.length < 1 ||
      game ||
      (value.matchIndex === matches.length - 1 && current.results.length === 2)
    )
      return null;
  } else {
    if (current.results.length > 1) return null;
    if (phase === TournamentPhase.ready && game) return null;
    if (
      phase === TournamentPhase.playing &&
      (!game || isWon(game) || game.boardCode !== current.boardCode)
    )
      return null;
  }
  return { names, matches, matchIndex: value.matchIndex, phase, game };
}
"}

